class Solution {
public:
    long long minCost(int n, string colors, vector<vector<int>>& edges) {
        vector<vector<int>> g(n);
        for (auto &e : edges) {
            int u = e[0], v = e[1];
            g[u].push_back(v);
            g[v].push_back(u);
        }

        vector<int> parent(n, -1);
        vector<int> order;
        order.reserve(n);
        stack<int> st;
        st.push(0);
        parent[0] = -2;                     // mark root

        while (!st.empty()) {
            int u = st.top(); st.pop();
            order.push_back(u);
            for (int v : g[u]) {
                if (parent[v] == -1) {
                    parent[v] = u;
                    st.push(v);
                }
            }
        }

        vector<int> sz(n, 1);
        vector<long long> dp(n, 0);
        long long base = 0;
        long long best = 0;

        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            long long weight = 0;
            // accumulate children sizes and dp contributions
            for (int v : g[u]) {
                if (parent[v] == u) {
                    sz[u] += sz[v];
                }
            }
            // compute weight after size is known
            if (colors[u] == 'R') {
                weight = sz[u];
                base += sz[u];
            } else {
                weight = - (long long)sz[u];
            }

            long long cur = weight;
            for (int v : g[u]) {
                if (parent[v] == u) {
                    cur += max(0LL, dp[v]);
                }
            }
            dp[u] = cur;
            best = max(best, dp[u]);
        }

        return base - max(0LL, best);
    }
};
